sys_script_include.script:
var TaskPriorityColor = Class.create();
TaskPriorityColor.prototype = {
    initialize: function() {},

    // Diese Funktion gibt die entsprechende Farbe basierend auf der Priorität zurück
    getPriorityColor: function(priority) {
        var priorityColor = '';

        // Berechne die Farbe basierend auf der Priorität
        if (priority == '3') {
            priorityColor = 'yellow';
        } else if (priority == '2') {
            priorityColor = 'brown';
        } else if (priority == '1') {
            priorityColor = 'green';
        } else if (priority == '4') {
            priorityColor = 'orange';
        } else {
            priorityColor = 'gray';  // Standardfarbe, falls keine Übereinstimmung
        }

        return priorityColor;
    },

    type: 'TaskPriorityColor'
};
